63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /**
71	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
72	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
73	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
74	     */
75	    private static final Pattern EMAIL_PATTERN =
76	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    public OwnerRestControllerV1(ClinicService clinicService,
87	                                 OwnerMapper ownerMapper,
88	                                 PetMapper petMapper,
89	                                 VisitMapper visitMapper) {
90	        this.clinicService = clinicService;
91	        this.ownerMapper = ownerMapper;
92	        this.petMapper = petMapper;
93	        this.visitMapper = visitMapper;
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
99	        Collection<Owner> owners;
100	        if (lastName != null) {
101	            owners = this.clinicService.findOwnerByLastName(lastName);
102	        } else {
103	            owners = this.clinicService.findAllOwners();
104	        }
105	        if (owners.isEmpty()) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
114	        Owner owner = this.clinicService.findOwnerById(ownerId);
115	        if (owner == null) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
124	        List<String> missingFields = new ArrayList<>();
125	        if (isBlank(ownerFieldsDto.getFirstName())) {
126	            missingFields.add("firstName");
127	        }
128	        if (isBlank(ownerFieldsDto.getLastName())) {
129	            missingFields.add("lastName");
130	        }
131	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
132	        if (isBlank(normalizedAddress)) {
133	            missingFields.add("address");
134	        }
135	        if (isBlank(ownerFieldsDto.getCity())) {
136	            missingFields.add("city");
137	        }
138	        if (isBlank(ownerFieldsDto.getTelephone())) {
139	            missingFields.add("telephone");
140	        }
141	        if (!missingFields.isEmpty()) {
142	            throw new MissingOwnerFieldsException(missingFields);
143	        }
144	        LocalDate today = LocalDate.now();
145	        long registeredToday = this.clinicService.findAllOwners().stream()
146	            .filter(existing -> today.equals(existing.getRegistrationDate()))
147	            .count();
148	        if (registeredToday >= 100) {
149	            throw new DailyRegistrationLimitException(
150	                "100 or more owners have already been registered today");
151	        }
152	        String city = ownerFieldsDto.getCity();
153	        long ownersInCity = this.clinicService.findAllOwners().stream()
154	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
155	            .count();
156	        if (ownersInCity >= 50) {
157	            throw new CityAtCapacityException(
158	                "the owner's city already contains 50 or more owners");
159	        }
160	        ownerFieldsDto.setAddress(normalizedAddress);
161	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
162	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
163	            .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
164	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())))
165	            .toList();
166	        String householdId = null;
167	        if (!householdMembers.isEmpty()) {
168	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
169	                throw new DuplicateHouseholdException(
170	                    "an owner with the same last name and address already exists");
171	            }
172	            // Joining an existing household: share a stable identifier with every member,
173	            // backfilling any members created before the household was formed.
174	            householdId = householdId(lastName, normalizedAddress);
175	            for (Owner member : householdMembers) {
176	                if (!householdId.equals(member.getHouseholdId())) {
177	                    member.setHouseholdId(householdId);
178	                    this.clinicService.saveOwner(member);
179	                }
180	            }
181	        }
182	        String telephone = toE164(ownerFieldsDto.getTelephone());
183	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
184	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
185	        if (telephoneInUse) {
186	            throw new DuplicateTelephoneException(
187	                "an owner with the same E.164 telephone already exists");
188	        }
189	        ownerFieldsDto.setTelephone(telephone);
190	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
191	        HttpHeaders headers = new HttpHeaders();
192	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
193	        if (owner.getRegistrationDate() == null) {
194	            owner.setRegistrationDate(LocalDate.now());
195	        }
196	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
197	        owner.setHouseholdId(householdId);
198	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
199	        this.clinicService.saveOwner(owner);
200	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
201	        headers.setLocation(UriComponentsBuilder.newInstance()
202	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
203	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
204	    }
