206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
209	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
210	        if (currentOwner == null) {
211	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	        }
213	        currentOwner.setAddress(ownerFieldsDto.getAddress());
214	        currentOwner.setCity(ownerFieldsDto.getCity());
215	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
216	        currentOwner.setLastName(ownerFieldsDto.getLastName());
217	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
218	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
219	        this.clinicService.saveOwner(currentOwner);
220	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
221	    }
222	
223	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
224	    @Transactional
225	    @Override
226	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
227	        Owner owner = this.clinicService.findOwnerById(ownerId);
228	        if (owner == null) {
229	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
230	        }
231	        this.clinicService.deleteOwner(owner);
232	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
233	    }
234	
235	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
236	    @Override
237	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
238	        Owner owner = this.clinicService.findOwnerById(ownerId);
239	        if (owner == null) {
240	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
241	        }
242	        HttpHeaders headers = new HttpHeaders();
243	        Pet pet = petMapper.toPet(petFieldsDto);
244	        owner.setId(ownerId);
245	        pet.setOwner(owner);
246	        pet.getType().setName(null);
247	        this.clinicService.savePet(pet);
248	        PetDto petDto = petMapper.toPetDto(pet);
249	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
250	            .buildAndExpand(pet.getId()).toUri());
251	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
252	    }
253	
254	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
255	    @Override
256	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
257	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
258	        if (currentOwner != null) {
259	            Pet currentPet = this.clinicService.findPetById(petId);
260	            if (currentPet != null) {
261	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
262	                currentPet.setName(petFieldsDto.getName());
263	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
264	                this.clinicService.savePet(currentPet);
265	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
266	            }
267	        }
268	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
269	    }
270	
271	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
272	    @Override
273	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
274	        HttpHeaders headers = new HttpHeaders();
275	        Visit visit = visitMapper.toVisit(visitFieldsDto);
276	        Pet pet = new Pet();
277	        pet.setId(petId);
278	        visit.setPet(pet);
279	        this.clinicService.saveVisit(visit);
280	        VisitDto visitDto = visitMapper.toVisitDto(visit);
281	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
282	            .buildAndExpand(visit.getId()).toUri());
283	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
284	    }
285	
286	
287	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
288	    @Override
289	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
290	        Owner owner = this.clinicService.findOwnerById(ownerId);
291	        if (owner != null) {
292	            Pet pet = owner.getPet(petId);
293	            if (pet != null) {
294	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
295	            }
296	        }
297	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
298	    }
299	
300	    private static boolean isBlank(String value) {
301	        return value == null || value.isBlank();
302	    }
303	
304	    /**
305	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
306	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
307	     * lower-cased so that last names are compared case-insensitively.
308	     */
309	    private static String normalizeHousehold(String value) {
310	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
311	    }
312	
313	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
314	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
315	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
316	
317	    /**
318	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
319	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
320	     * upper-cased, and common street-type abbreviations are expanded token-by-token
321	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
322	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
323	     * used for every address comparison (household-duplicate detection and the shared household id).
324	     */
325	    private static String normalizeAddress(String value) {
326	        if (value == null) {
327	            return "";
328	        }
329	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
330	        if (collapsed.isEmpty()) {
331	            return "";
332	        }
333	        String[] tokens = collapsed.split(" ");
334	        StringBuilder sb = new StringBuilder();
335	        for (int i = 0; i < tokens.length; i++) {
336	            if (i > 0) {
337	                sb.append(' ');
338	            }
339	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
340	        }
341	        return sb.toString();
342	    }
343	
344	    /**
345	     * Derives the stable {@code householdId} shared by all owners in a household. It is a
346	     * deterministic function of the normalized last name and address, so every owner that
347	     * shares those values maps to the same identifier regardless of creation order.
348	     */
349	    private static String householdId(String normalizedLastName, String normalizedAddress) {
350	        String key = normalizedLastName + "\n" + normalizedAddress;
351	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
352	    }
353	
354	    /**
355	     * Builds the {@code customerCode} assigned to a new owner, formatted
356	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
357	     * owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last name,
358	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the number
359	     * of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
360	     */
361	    private String nextCustomerCode(String city, String lastName) {
362	        String city3 = prefix3(city);
363	        String last3 = prefix3(lastName);
364	        long sequence = this.clinicService.findAllOwners().stream()
365	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
366	            .count() + 1L;
367	        return String.format("%s-%s-%04d", city3, last3, sequence);
368	    }
369	
370	    /** Upper-cased first three letters (any non-letter removed) of the given value. */
371	    private static String prefix3(String value) {
372	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
373	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
374	    }
375	
376	    /**
377	     * Counts the existing owners that share the given first name and last name, compared
378	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
379	     * owner currently being created is saved), so it reflects how many namesakes preceded the
380	     * new owner.
381	     */
382	    private int countNamesakes(String firstName, String lastName) {
383	        return (int) this.clinicService.findAllOwners().stream()
384	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
385	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
386	            .count();
387	    }
388	
389	    /**
390	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
391	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
392	     * national one, a single leading {@code '0'} is dropped, and the default country code
393	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'},
394	     * otherwise an {@link InvalidTelephoneException} is raised (reported to the client as 400).
395	     */
396	    private static String toE164(String telephone) {
397	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
398	        String digits;
399	        if (cleaned.startsWith("+")) {
400	            digits = cleaned.substring(1);
401	        } else {
402	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
403	            digits = "61" + national;
404	        }
405	        if (!digits.matches("[0-9]{8,15}")) {
406	            throw new InvalidTelephoneException(
407	                "telephone must form a valid E.164 number with 8 to 15 digits");
408	        }
409	        return "+" + digits;
410	    }
411	
412	    /**
413	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
414	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
415	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
416	     * stored and returned in canonical form.
417	     */
418	    private static String normalizeEmail(String email) {
419	        if (isBlank(email)) {
420	            return null;
421	        }
422	        String trimmed = email.trim();
423	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
424	            throw new InvalidEmailException("email must be a syntactically valid address");
425	        }
426	        return trimmed.toLowerCase(Locale.ROOT);
427	    }
428	}
